from (values
('127.40.d.1.A',2,'A student planning a turf grass SAE should begin by:','["setting goals and mapping out the work", "waiting for a customer", "picking a date at random", "avoiding a plan"]'::jsonb,0,'SAEs are planned, conducted, documented and evaluated.','original'),
('127.40.d.1.A',2,'After a season of mowing for pay as an SAE, the student should:','["ignore profit", "evaluate the results and costs", "delete the notes", "forget the work"]'::jsonb,1,'Evaluation completes the SAE cycle.','original'),
('127.40.d.1.B',2,'A turf SAE record book should show:','["only jokes", "only guesses", "hours worked, supplies bought and income", "only complaints"]'::jsonb,2,'Records support profit calculations.','original'),
('127.40.d.1.B',2,'Keeping turf SAE receipts helps a student to:','["hide costs", "avoid records", "lose track", "prove expenses accurately"]'::jsonb,3,'Receipts back up entries.','original'),
('127.40.d.1.C',2,'A student who leads a lawn-care committee in the chapter gains:','["leadership experience", "no confidence", "isolation", "fewer skills"]'::jsonb,0,'Leadership roles build skills.','original'),
('127.40.d.1.C',2,'Leadership opportunities help turf students to:','["avoid people", "become more well-rounded", "limit growth", "skip teams"]'::jsonb,1,'A well-rounded program includes leadership.','original'),
('127.40.d.1.D',2,'To plan the chapter''s turf service project, members use:','["no plan", "random ideas", "a strategic planning process", "secret rules"]'::jsonb,2,'Strategic planning sets goals and steps.','original'),
('127.40.d.1.D',2,'Mowing the school grounds as a chapter project is a way to:','["skip events", "hide effort", "avoid service", "take part in the local program of activities"]'::jsonb,3,'Projects are part of the program.','original'),
('127.40.d.2.A',3,'Which factor affects whether turf will establish well?','["sunlight, soil and drainage", "the team mascot", "the grass price", "the shop hours"]'::jsonb,0,'Site conditions determine success.','original'),
('127.40.d.2.A',3,'A shaded lawn needs grass that is:','["sun loving only", "shade tolerant", "plastic", "drought only"]'::jsonb,1,'Species vary in shade tolerance.','original'),
('127.40.d.2.B',3,'A site assessment checklist is used to:','["mow lawns", "buy seed", "record conditions at a turf site", "advertise services"]'::jsonb,2,'Checklists organize observations.','original'),
('127.40.d.2.B',3,'An item on a turf site checklist is:','["the client''s hobbies", "the radio station", "the tax rate", "soil pH and slope"]'::jsonb,3,'Soil and slope influence plans.','original'),
('127.40.d.2.C',3,'A site preparation plan for new turf would include:','["clearing debris, grading and soil testing", "planting on rocks", "adding trash", "skipping soil prep"]'::jsonb,0,'Preparation precedes planting.','original'),
('127.40.d.2.C',3,'Before laying sod, the soil surface should be:','["covered in debris", "smooth, firm and weed free", "rutted and rocky", "left uneven"]'::jsonb,1,'Good prep prevents problems.','original'),
('127.40.d.3.A',3,'Bermudagrass is a good choice for sunny Texas sites because it is:','["cold only", "water-hungry only", "heat and drought tolerant", "shade only"]'::jsonb,2,'Bermuda thrives in full sun.','original'),
('127.40.d.3.A',3,'A cultivar is:','["a pest", "a fertilizer", "a tool", "a cultivated variety of a grass species"]'::jsonb,3,'Cultivars are selected types.','original'),
('127.40.d.3.B',3,'A common insect pest of lawns is the:','["white grub", "honeybee", "earthworm", "ladybug"]'::jsonb,0,'Grubs eat roots.','original'),
('127.40.d.3.B',3,'Brown patch is a turf:','["tool", "fungal disease", "herbicide", "insect"]'::jsonb,1,'Pathogens cause turf diseases.','original'),
('127.40.d.3.C',3,'A weed with narrow, grass-like leaves is a:','["tree", "vegetable", "grassy weed", "broadleaf weed"]'::jsonb,2,'Weed type guides herbicide choice.','original'),
('127.40.d.3.C',3,'Dandelion and clover are examples of:','["grassy weeds", "sedges", "mosses", "broadleaf weeds"]'::jsonb,3,'Broadleaf weeds have wide leaves.','original'),
('127.40.d.3.D',3,'Grading a site so it slopes slightly away from buildings helps to:','["move water away", "trap water", "kill grass", "flood foundations"]'::jsonb,0,'Positive drainage protects structures.','original'),
('127.40.d.3.D',3,'Poor grading can lead to:','["better growth", "standing water in low spots", "perfect drainage", "more sunshine"]'::jsonb,1,'Low spots collect water.','original'),
('127.40.d.3.E',3,'Compacted soil hurts turf because it:','["adds nutrients", "drains too fast", "limits air, water and root growth", "improves roots"]'::jsonb,2,'Pore space is lost.','original'),
('127.40.d.3.E',3,'A site used heavily by foot traffic is likely to have:','["loose soil", "extra nutrients", "too much air", "soil compaction"]'::jsonb,3,'Traffic packs soil.','original'),
('127.40.d.3.F',3,'Core aeration reduces compaction by:','["pulling plugs to open the soil", "adding water only", "spraying chemicals", "raising the mower"]'::jsonb,0,'Holes let air and water in.','original'),
('127.40.d.3.F',3,'The best time to aerate warm-season turf is generally:','["during dormancy", "late spring to early summer", "mid-fall frost", "midwinter"]'::jsonb,1,'Active growth speeds recovery.','original'),
('127.40.d.3.G',3,'Laying rolls of grass with soil attached is called:','["hydromulching", "sprigging", "sodding", "seeding"]'::jsonb,2,'Sod gives instant cover.','original'),
('127.40.d.3.G',3,'Spraying a slurry of seed, mulch and water is:','["plugging", "sodding", "aerating", "hydromulching"]'::jsonb,3,'Hydroseeding covers large areas quickly.','original'),
('127.40.d.3.H',3,'Warm-season grasses are best installed in:','["late spring through summer", "midwinter", "just before frost", "late fall"]'::jsonb,0,'They need warm soil to root.','original'),
('127.40.d.3.H',3,'Timing matters for turf installation because it affects:','["the customer''s age", "how quickly the grass establishes", "the paint color", "the store hours"]'::jsonb,1,'Right timing aids rooting.','original'),
('127.40.d.4.A',3,'Mowing bermudagrass lower than most lawn species shows that:','["height is random", "all grass is cut equally", "mowing height depends on the grass type", "height never matters"]'::jsonb,2,'Species differ in ideal height.','original'),
('127.40.d.4.A',3,'Tall fescue is usually mowed:','["lower than bermudagrass", "with a scalping cut", "to ground level", "higher than bermudagrass"]'::jsonb,3,'Cool-season grasses tolerate taller mowing.','original'),
('127.40.d.4.B',3,'The one-third rule says to remove no more than:','["one third of the leaf at a time", "all of the leaf", "half the plant", "two thirds"]'::jsonb,0,'Cutting too much stresses turf.','original'),
('127.40.d.4.B',3,'Mowing frequency should be based on:','["the customer''s age", "grass growth rate", "the calendar only", "the neighbor''s habits"]'::jsonb,1,'Fast growth needs frequent mowing.','original'),
('127.40.d.4.C',3,'Athletic fields differ from home lawns because they need:','["no maintenance", "only shade grass", "durable turf for heavy wear", "fewer plants"]'::jsonb,2,'Sports turf is intensively managed.','original'),
('127.40.d.4.C',3,'Commercial turf sites are usually maintained for:','["hay production", "grazing", "no appearance", "a neat, uniform appearance"]'::jsonb,3,'Commercial grounds present a business image.','original'),
('127.40.d.4.D',3,'Most turf needs about how much water per week?','["about one inch", "one gallon", "ten inches", "none"]'::jsonb,0,'One inch from rain or irrigation is common.','original'),
('127.40.d.4.D',3,'Watering deeply but less often encourages:','["weeds", "deep roots", "shallow roots", "brown patch only"]'::jsonb,1,'Deep watering builds drought tolerance.','original'),
('127.40.d.4.E',4,'Thatch is:','["a fertilizer", "a type of weed", "a layer of dead and living stems and roots above the soil", "a tool"]'::jsonb,2,'It builds up between grass and soil.','original'),
('127.40.d.4.E',4,'A common way to remove excess thatch is:','["watering more", "mowing higher", "adding fertilizer", "dethatching or core aeration"]'::jsonb,3,'Mechanical removal fixes it.','original'),
('127.40.d.4.F',3,'The three numbers on a fertilizer bag stand for:','["nitrogen, phosphorus and potassium", "height, width and depth", "sun, rain and soil", "price, weight and size"]'::jsonb,0,'N-P-K.','original'),
('127.40.d.4.F',3,'Turf grass most needs which nutrient for green color and growth?','["helium", "nitrogen", "gold", "sand"]'::jsonb,1,'Nitrogen drives leaf growth.','original'),
('127.40.d.4.G',4,'A turf fertilization plan protects water quality by:','["applying before storms", "spreading on hard surfaces", "avoiding applications before heavy rain", "over-applying"]'::jsonb,2,'Prevents runoff.','original'),
('127.40.d.4.G',4,'Soil testing before fertilizing helps to:','["waste product", "guess rates", "raise costs", "apply only the needed nutrients"]'::jsonb,3,'Tests guide rates.','original'),
('127.40.d.4.H',3,'The first step of Integrated Pest Management is to:','["identify the pest correctly", "spray everything", "buy chemicals", "ignore damage"]'::jsonb,0,'Identification guides action.','original'),
('127.40.d.4.H',3,'IPM combines cultural, biological and chemical controls to:','["use only chemicals", "manage pests with minimal risk", "skip scouting", "avoid all control"]'::jsonb,1,'It is a balanced approach.','original'),
('127.40.d.4.I',3,'Before spraying, an applicator should:','["spray in wind", "guess the rate", "calibrate the sprayer and read the label", "skip PPE"]'::jsonb,2,'Calibration ensures correct dose.','original'),
('127.40.d.4.I',3,'Spray drift can be reduced by:','["spraying in storms", "using more pressure", "spraying near water", "not spraying on windy days"]'::jsonb,3,'Wind carries droplets.','original'),
('127.40.d.4.J',3,'A pesticide label is:','["the legal instruction for use", "an advertisement", "a suggestion", "optional reading"]'::jsonb,0,'Label directions are law.','original'),
('127.40.d.4.J',3,'A safety data sheet lists:','["mowing heights", "hazards and emergency steps for a product", "grass seed names", "store prices"]'::jsonb,1,'SDS informs safe handling.','original'),
('127.40.d.5.A',2,'To assess a prospective client''s needs, a turf manager should:','["ignore requests", "skip the visit", "ask about goals, budget and site use", "pick a price randomly"]'::jsonb,2,'Good service starts with listening.','original'),
('127.40.d.5.A',2,'A walk-through with a prospective client helps to:','["delay the work", "hide costs", "avoid questions", "see the site and discuss expectations"]'::jsonb,3,'It sets expectations.','original'),
('127.40.d.5.B',3,'Business costs for a turf company include:','["insurance, fuel and equipment", "only labor", "only mulch", "only seed"]'::jsonb,0,'Overhead matters.','original'),
('127.40.d.5.B',3,'If a mower costs $2,000 and lasts 5 years, its yearly cost is:','["$200", "$400", "$2,000", "$10,000"]'::jsonb,1,'2,000 divided by 5 is 400.','original'),
('127.40.d.5.C',3,'A maintenance schedule lists:','["the weather", "the mascot", "tasks and when they will be done", "the mortgage"]'::jsonb,2,'Schedules guide service.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
